window.RP_SESSION={"id":"S-2ea137f21255","messages":[{"id":"RP-II-0052020","time":"2026-03-02T12:14:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"빗줄기가 투둑투둑 잔디 밭을 건드니, 마리우스는 멍하니 그것만을 바라보았습니다. 유일한 낙이던 잔디밭에 앉아 멍 때리는 것은 불가피하게 되었으니···. 그냥 대장간 문, 계단 위에서 가만히 비가 오는 것을 바라볼 뿐이었지요.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0052021","time":"2026-03-02T12:45:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"한숨 깊게 내쉬고 누구라도 안 오나···. 싶어 조용히 밖만 바라봅니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0052022","time":"2026-03-02T12:45:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"애꿎은 나뭇가지와 돌만 집어 탁탁거리지만, 한참 물에 젖어버려 별 수가 없죠.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0052023","time":"2026-03-02T14:44:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-b6d81d634c6e"]}]};
